<?php
require dirname(__DIR__).'/includes/bootstrap.php'; require_permission('giftcards.manage'); $bid=current_branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $code=trim($_POST['code']??'') ?: 'GC-'.strtoupper(bin2hex(random_bytes(4))); $bal=(float)$_POST['initial_balance']; q('INSERT INTO gift_cards(branch_id,code,customer_id,initial_balance,current_balance,expiry_date,status,created_at) VALUES(?,?,?,?,?,?,"active",NOW())',[$bid,$code,(int)($_POST['customer_id']??0)?:null,$bal,$bal,$_POST['expiry_date']?:null]); $id=(int)db()->lastInsertId(); q('INSERT INTO gift_card_transactions(gift_card_id,amount,type,created_by,created_at) VALUES(?,?,"issue",?,NOW())',[$id,$bal,$_SESSION['user_id']]); flash('success','Gift card created: '.$code); redirect('modules/gift_cards.php');}
$rows=all('SELECT gc.*,c.full_name customer FROM gift_cards gc LEFT JOIN customers c ON c.id=gc.customer_id WHERE gc.branch_id=? ORDER BY gc.id DESC',[$bid]); $title='Gift Cards'; $subtitle='Create gift card, balance, expiry and usage history.'; include dirname(__DIR__).'/includes/header.php';?><section class="card"><h2>Create Gift Card</h2><form method="post"><?=csrf_field()?><div class="form-grid"><div class="form-group"><label>Code (optional)</label><input name="code" placeholder="Auto if blank"></div><div class="form-group"><label>Customer</label><select name="customer_id"><option value="">No customer</option><?php foreach(customers_options() as $id=>$l):?><option value="<?=e($id)?>"><?=e($l)?></option><?php endforeach;?></select></div><div class="form-group"><label>Initial Balance</label><input type="number" step="0.01" name="initial_balance" required></div><div class="form-group"><label>Expiry Date</label><input type="date" name="expiry_date"></div></div><button class="btn">Create Gift Card</button></form></section><div class="table-wrap"><table><thead><tr><th>Code</th><th>Customer</th><th>Initial</th><th>Balance</th><th>Expiry</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['code'])?></td><td><?=e($r['customer'])?></td><td><?=money($r['initial_balance'])?></td><td><?=money($r['current_balance'])?></td><td><?=e($r['expiry_date'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></div><?php include dirname(__DIR__).'/includes/footer.php'; ?>